import { createClient } from "@clickhouse/client";

type DailyRevenue = { day: string; revenue_cents: string };
const clickhouseUrl = process.env.CLICKHOUSE_URL;
if (!clickhouseUrl) throw new Error("CLICKHOUSE_URL is required");
const client = createClient({ url: clickhouseUrl });

export async function getDailyRevenue(start: Date, end: Date): Promise<DailyRevenue[]> {
  if (start >= end) throw new RangeError("start must be earlier than end");
  const result = await client.query({
    query: "SELECT toDate(created_at) AS day, toString(sum(total_cents)) AS revenue_cents FROM orders WHERE created_at >= parseDateTimeBestEffort({start:String}) AND created_at < parseDateTimeBestEffort({end:String}) GROUP BY day ORDER BY day",
    query_params: { start: start.toISOString(), end: end.toISOString() },
    format: "JSONEachRow",
  });
  return result.json<DailyRevenue[]>();
}

