import { DuckDBInstance } from "@duckdb/node-api";

type DailyRevenue = { day: string; revenue_cents: bigint };
const instance = await DuckDBInstance.create(process.env.ANALYTICS_DB_PATH ?? "analytics.db");
const connection = await instance.connect();

export async function getDailyRevenue(start: Date, end: Date): Promise<DailyRevenue[]> {
  if (start >= end) throw new RangeError("start must be earlier than end");
  const statement = await connection.prepare(
    "SELECT CAST(CAST(created_at AS DATE) AS VARCHAR) AS day, sum(total_cents) AS revenue_cents FROM orders WHERE created_at >= CAST($start AS TIMESTAMPTZ) AND created_at < CAST($end AS TIMESTAMPTZ) GROUP BY day ORDER BY day",
  );
  statement.bindVarchar("start", start.toISOString());
  statement.bindVarchar("end", end.toISOString());
  const reader = await statement.runAndReadAll();
  return reader.getRowObjects() as DailyRevenue[];
}
